对象最强大的用法是和{{term:数组}}结合——**对象{{term:数组}}**：

```js
let composers = [
  { name: "巴赫", period: "巴洛克", country: "德国" },
  { name: "莫扎特", period: "古典主义", country: "奥地利" },
  { name: "肖邦", period: "浪漫主义", country: "波兰" }
];
// 用 forEach 遍历
composers.forEach(function(c) {
  console.log(`${c.name} — ${c.period}`);
});
```

这才是实际开发中最常见的数据形式——{{term:数组}}里包着对象，每个对象代表一条记录。就像 Excel 表格：每一行是{{term:数组}}的一项，每一列是对象的{{term:属性}}！

下面的代码用对象{{term:数组}}存储了作曲家信息，用 `forEach` 遍历并生成卡片：

```js
// 对象数组：每个 {} 是一个对象，用 .属性名 访问里面的值
let composers = [
  { name: "巴赫", period: "巴洛克", piece: "赋格的艺术" },
  { name: "莫扎特", period: "古典主义", piece: "魔笛" },
  { name: "肖邦", period: "浪漫主义", piece: "夜曲" }
];
let html = "";
composers.forEach(function(c) {
  html += `
    <div class="card">
      <h2>${c.name}</h2>           <!-- c.name：访问对象的 name 属性 -->
      <p>时期：${c.period}</p>     <!-- c.period：访问 period 属性 -->
      <p>代表作：《${c.piece}》</p> <!-- c.piece：访问 piece 属性 -->
    </div>
  `;
});
```

切换到 {{term:JS}} {{term:标签}}页查看完整代码——对象数据的结构和用途一目了然。

